import apiClient from './apiClient';

const videoService = {
  // Get videos for a course
  getCourseVideos: async (courseId) => {
    try {
      const response = await apiClient.get(`/video/courses/${courseId}/video`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Upload video for a course
  uploadVideo: async (courseId, videoData) => {
    try {
      const formData = new FormData();
      formData.append('title', videoData.title);
      formData.append('description', videoData.description);
      if (videoData.file) {
        formData.append('video', videoData.file);
      }
      if (videoData.url) {
        formData.append('url', videoData.url);
      }

      const response = await apiClient.post(`/video/courses/${courseId}/video`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Get video by ID
  getVideoById: async (videoId) => {
    try {
      const response = await apiClient.get(`/video/${videoId}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  // Update video progress
  updateVideoProgress: async (videoId, progressData) => {
    try {
      const response = await apiClient.patch(`/video/${videoId}/progress`, progressData);
      return response.data;
    } catch (error) {
      throw error;
    }
  }
};

export default videoService;
